o);\n}\n\nfn main() {\n    // Calling the method is still fine, as i32 implements Debug.\n    some_func(5i32);\n\n    // This would fail to compile now:\n    // struct WithoutDebug;\n    // some_func(WithoutDebug);\n}\n```\n\nRust only looks at the signature of the called function, as such it must\nalready specify all requirements that will be used for every type parameter.\n"},"level":"error","spans":[{"file_name":"src/main.rs","byte_start":288,"byte_end":298,"line_start":13,"line_end":13,"column_start":5,"column_end":15,"is_primary":true,"text":[{"text":"    score: f64,","highlight_start":5,"highlight_end":15}],"label":"the trait `Eq` is not implemented for `f64`","suggested_replacement":null,"suggestion_applicability":null,"expansion":{"span":{"file_name":"src/main.rs","byte_start":228,"byte_end":230,"line_start":10,"line_end":10,"column_start":41,"column_end":43,"is_primary":false,"text":[{"text":"#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]","highlight_start":41,"highlight_end":43}],"label":null,"suggested_replacement":null,"suggestion_applicability":null,"expansion":null},"macro_decl_name":"#[derive(Eq)]","def_site_span":{"file_name":"/rustc/ded5c06cf21d2b93bffd5d884aa6e96934ee4234/library/core/src/cmp.rs","byte_start":13141,"byte_end":13153,"line_start":356,"line_end":356,"column_start":1,"column_end":13,"is_primary":false,"text":[],"label":null,"suggested_replacement":null,"suggestion_applicability":null,"expansion":null}}}],"children":[{"message":"the following other types implement trait `Eq`:\n  i128\n  i16\n  i32\n  i64\n  i8\n  isize\n  u128\n  u16\nand 4 others","code":null,"level":"help","spans":[],"children":[],"rendered":null},{"message":"required by a bound in `AssertParamIsEq`","code":null,"level":"note","spans":[{"file_name":"/rustc/ded5c06cf21d2b93bffd5d884aa6e96934ee4234/library/core/src/cmp.rs","byte_start":13514,"byte_end":13562,"line_start":367,"line_end":367,"column_start":1,"column_end":49,"is_primary":true,"text":[],"labe