+#!/usr/bin/env python3
+"""zoxide - A smarter cd command for your terminal."""
+
+import argparse
+import os
+import sys
+import json
+import re
+import pwd
+import grp
+import subprocess
+import shlex
+from pathlib import Path
+from typing import List, Optional, Tuple, Dict, Any
+
+VERSION = "0.9.9"
+AUTHOR = "Ajeet D'Souza <98ajeet@gmail.com>"
+URL = "https://github.com/ajeetdsouza/zoxide"
+
+# Environment variables
+ZO_DATA_DIR = os.environ.get("_ZO_DATA_DIR")
+ZO_ECHO = os.environ.get("_ZO_ECHO", "0")
+ZO_EXCLUDE_DIRS = os.environ.get("_ZO_EXCLUDE_DIRS", "")
+ZO_FZF_OPTS = os.environ.get("_ZO_FZF_OPTS", "")
+ZO_MAXAGE = int(os.environ.get("_ZO_MAXAGE", "10000"))
+ZO_RESOLVE_SYMLINKS = os.environ.get("_ZO_RESOLVE_SYMLINKS", "0")
+
+
+def get_data_dir() -> str:
+    """Get the data directory based on platform."""
+    if ZO_DATA_DIR:
+        return ZO_DATA_DIR
+
+    if sys.platform == "win32":
+        localappdata = os.environ.get("LOCALAPPDATA", os.path.expanduser("~\\AppData\\Local"))
+        return os.path.join(localappdata, "zoxide")
+    elif sys.platform == "darwin":
+        return os.path.join(os.path.expanduser("~"), "Library", "Application Support", "zoxide")
+    else:
+        xdg_data_home = os.environ.get("XDG_DATA_HOME", os.path.join(os.path.expanduser("~"), ".local", "share"))
+        return os.path.join(xdg_data_home, "zoxide")
+
+
+def get_db_path() -> str:
+    """Get the database file path."""
+    data_dir = get_data_dir()
+    os.makedirs(data_dir, exist_ok=True)
+    return os.path.join(data_dir, "db.json")
+
+
+def load_db() -> List[Dict[str, Any]]:
+    """Load the database from disk."""
+    db_path = get_db_path()
+    if not os.path.exists(db_path):
+        return []
+
+    try:
+        with open(db_path, "r") as f:
+            data = json.load(f)
+            if isinstance(data, list):
+                return data
+            elif isinstance(data, dict) and "entries" in data:
+                return data["entries"]
+            else:
+                return []
+    except (json.JSONDecodeError, IOError):
+        return []
+
+
+def save_db(entries: List[Dict[str, Any]]) -> None:
+    """Save the database to disk."""
+    db_path = get_db_path()
+    os.makedirs(os.path.dirname(db_path), exist_ok=True)
+
+    with open(db_path, "w") as f:
+        json.dump({"entries": entries}, f, indent=2)
+
+
+def parse_path(path: str) -> Tuple[str, bool]:
+    """Parse a path, resolving symlinks if requested."""
+    if path == "-":
+        return os.getcwd(), False
+
+    resolved = os.path.realpath(path) if ZO_RESOLVE_SYMLINKS else path
+    return resolved, path != resolved
+
+
+def is_excluded(path: str) -> bool:
+    """Check if a path should be excluded based on _ZO_EXCLUDE_DIRS."""
+    if not ZO_EXCLUDE_DIRS:
+        return False
+
+    home = os.path.expanduser("~")
+    if path == home or path.startswith(home + "/"):
+        return True
+
+    sep = ":" if sys.platform != "win32" else ";"
+    patterns = [p.strip() for p in ZO_EXCLUDE_DIRS.split(sep) if p.strip()]
+
+    for pattern in patterns:
+        if fnmatch.fnmatch(path, pattern):
+            return True
+        if fnmatch.fnmatch(os.path.basename(path), pattern):
+            return True
+
+    return False
+
+
+def fnmatch(pattern: str, string: str) -> bool:
+    """Simple fnmatch implementation."""
+    if pattern.endswith("*"):
+        return string.startswith(pattern[:-1])
+    return pattern == string
+
+
+def add_path(path: str, score: int = 1) -> int:
+    """Add a path to the database."""
+    resolved, _ = parse_path(path)
+
+    if is_excluded(resolved):
+        print(f"zoxide: {path} is excluded", file=sys.stderr)
+        return 1
+
+    db = load_db()
+
+    # Check if path already exists
+    for entry in db:
+        if entry["path"] == resolved:
+            entry["score"] = score
+            entry["age"] = 0
+            entry["rank"] = entry["rank"] + 1
+            save_db(db)
+            return 0
+
+    # New entry
+    entry = {
+        "path": resolved,
+        "score": score,
+        "age": 0,
+        "rank": len(db) + 1
+    }
+    db.append(entry)
+    save_db(db)
+
+    return 0
+
+
+def query_path(query: str, exclude: Optional[str] = None, fzf: bool = False) -> int:
+    """Query the database for a matching path."""
+    db = load_db()
+
+    if not db:
+        print("zoxide: no entries found", file=sys.stderr)
+        return 1
+
+    # Filter and sort entries
+    results = []
+    for entry in db:
+        path = entry["path"]
+        if exclude and path == exclude:
+            continue
+        if query.lower() in path.lower():
+            results.append(entry)
+
+    if not results:
+        print("zoxide: no entries found", file=sys.stderr)
+        return 1
+
+    # Sort by score (descending)
+    results.sort(key=lambda x: x["score"], reverse=True)
+
+    if fzf:
+        # Use fzf for interactive selection
+        try:
+            result = subprocess.run(
+                ["fzf"],
+                input="\n".join([f"{r['score']} {r['path']}" for r in results]),
+                capture_output=True,
+                text=True,
+                timeout=10
+            )
+            if result.returncode == 0 and result.stdout.strip():
+                selected = result.stdout.strip().split()[1]
+                print(selected)
+                return 0
+        except (subprocess.TimeoutExpired, FileNotFoundError):
+            pass
+
+    # Print top result
+    print(results[0]["path"])
+    return 0
+
+
+def remove_path(path: str) -> int:
+    """Remove a path from the database."""
+    db = load_db()
+
+    for i, entry in enumerate(db):
+        if entry["path"] == path:
+            db.pop(i)
+            save_db(db)
+            return 0
+
+    print(f"zoxide: {path} not found", file=sys.stderr)
+    return 1
+
+
+def init_shell(shell: str, cmd: Optional[str] = None, no_cmd: bool = False, hook: Optional[str] = None) -> int:
+    """Generate shell initialization code."""
+    if shell == "bash":
+        return generate_bash_init(cmd, no_cmd, hook)
+    elif shell == "zsh":
+        return generate_zsh_init(cmd, no_cmd, hook)
+    elif shell == "fish":
+        return generate_fish_init(cmd, no_cmd, hook)
+    elif shell == "powershell":
+        return generate_powershell_init(cmd, no_cmd, hook)
+    elif shell == "elvish":
+        return generate_elvish_init(cmd, no_cmd, hook)
+    elif shell == "nushell":
+        return generate_nushell_init(cmd, no_cmd, hook)
+    elif shell == "posix":
+        return generate_posix_init(cmd, no_cmd, hook)
+    else:
+        print(f"zoxide: unknown shell: {shell}", file=sys.stderr)
+        return 1
+
+
+def generate_bash_init(cmd: Optional[str] = None, no_cmd: bool = False, hook: Optional[str] = None) -> int:
+    """Generate bash initialization code."""
+    if no_cmd:
+        print("# shellcheck shell=bash\n\n# =============================================================================\n#\n# Utility functions for zoxide.\n#\n\n# pwd based on the value of _ZO_RESOLVE_SYMLINKS.\nfunction __zoxide_pwd() {\n    \\builtin pwd -L\n}\n\n# cd + custom logic based on the value of _ZO_ECHO.\nfunction __zoxide_cd() {\n    # shellcheck disable=SC2164\n    \\builtin cd -- \"$@\"\n}\n\n# =============================================================================\n#\n# Hook configuration for zoxide.\n#\n\n# Hook to add new entries to the database.\n__zoxide_oldpwd=\"$(__zoxide_pwd)\"\n\nfunction __zoxide_hook() {\n    \\builtin local -r retval=\"$?\"\n    \\builtin local pwd_tmp\n    pwd_tmp=\"$(__zoxide_pwd)\"\n    if [[ ${__zoxide_oldpwd} != \"${pwd_tmp}\" ]]; then\n        __zoxide_oldpwd=\"${pwd_tmp}\"\n        \\command zoxide add -- \"${__zoxide_oldpwd}\"\n    fi\n    return \"${retval}\"\n}\n\n# Initialize hook.\nif [[ ${PROMPT_COMMAND:=} != *\\'__zoxide_hook\\'* ]]; then\n    if [[ \"$(declare -p PROMPT_COMMAND 2\\>\\&1)\" == \"declare -a\"* ]]; then\n        PROMPT_COMMAND=(\"${PROMPT_COMMAND[@]}\" __zoxide_hook)\n    else\n        # shellcheck disable=SC2128,SC2178\n        PROMPT_COMMAND=\"${PROMPT_COMMAND%\"${PROMPT_COMMAND##*[![:space:];]}\"}\"\n        # shellcheck disable=SC2128,SC2178\n        PROMPT_COMMAND=\"${PROMPT_COMMAND:+${PROMPT_COMMAND};}__zoxide_hook\"\n    fi\nfi\n\n# Report common issues.\nfunction __zoxide_doctor() {\n    [[ ${_ZO_DOCTOR:-1} -eq 0 ]] \\&\\& return 0\n    # shellcheck disable=SC2199\n    [[ ${PROMPT_COMMAND[@]:-} == *\\'__zoxide_hook\\'* ]] \\&\\& return 0\n    # shellcheck disable=SC2199\n    [[ ${__vsc_original_prompt_command[@]:-} == *\\'__zoxide_hook\\'* ]] \\&\\& return 0\n\n    _ZO_DOCTOR=0\n    \\builtin printf \\'%s\\n\\' \\\n        \\'zoxide: detected a possible configuration issue.\\' \\\n        \\'Please ensure that zoxide is initialized right at the end of your shell configuration file (usually ~/.bashrc).\\' \\\n        \\'\\' \\\n        \\'If the issue persists, consider filing an issue at:\\' \\\n        \\'https://github.com/ajeetdsouza/zoxide/issues\\' \\\n        \\'\\' \\\n        \\'Disable this message by setting _ZO_DOCTOR=0.\\' \\\n        \\'\\' \\>\\&2\n}\n\n# =============================================================================\n#\n# When using zoxide with --no-cmd, alias these internal functions as desired.\n#\n\n__zoxide_z_prefix=\\'z#\\'\\n\n\n# Jump to a directory using only keywords.\nfunction __zoxide_z() {\n    __zoxide_doctor\n\n    # shellcheck disable=SC2199\n    if [[ $# -eq 0 ]]; then\n        __zoxide_cd ~\n    elif [[ $# -eq 1 \\&\\& $1 == \\'-\\' ]]; then\n        __zoxide_cd \"${OLDPWD}\"\n    elif [[ $# -eq 1 \\&\\& -d $1 ]]; then\n        __zoxide_cd \"$1\"\n    elif [[ $# -eq 2 \\&\\& $1 == \\'--\\' ]]; then\n        __zoxide_cd \"$2\"\n    elif [[ ${@: -1} == \"${__zoxide_z_prefix}\"?* ]]; then\n        # shellcheck disable=SC2124\n        \\builtin local result=\"${@: -1}\"\n        __zoxide_cd \"${result:${#__zoxide_z_prefix}}\"\n    else\n        \\builtin local result\n        # shellcheck disable=SC2312\n        result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" -- \"$@\")\" \\&\\&\n            __zoxide_cd \"${result}\"\n    fi\n}\n\n# Jump to a directory using interactive search.\nfunction __zoxide_zi() {\n    __zoxide_doctor\n    \\builtin local result\n    result=\"$(\\command zoxide query --interactive -- \"$@\")\" \\&\\& __zoxide_cd \"${result}\"\n}\n\n# =============================================================================\n#\n# Commands for zoxide. Disable these using --no-cmd.\n#\n\n\\builtin unalias z \\&\\>/dev/null || \\builtin true\nfunction z() {\n    __zoxide_z \"$@\"\n}\n\n\\builtin unalias zi \\&\\>/dev/null || \\builtin true\nfunction zi() {\n    __zoxide_zi \"$@\"\n}\n\n# Load completions.\n# - Bash 4.4+ is required to use `@Q`.\n# - Completions require line editing. Since Bash supports only two modes of\n#   line editing (`vim` and `emacs`), we check if either them is enabled.\n# - Completions don\\'t work on `dumb` terminals.\nif [[ ${BASH_VERSINFO[0]:-0} -eq 4 \\&\\& ${BASH_VERSINFO[1]:-0} -ge 4 || ${BASH_VERSINFO[0]:-0} -ge 5 ]] \\&\\&\n    [[ :\"${SHELLOPTS}\": =~ :(vi|emacs): \\&\\& ${TERM} != \\'dumb\\' ]]; then\n\n    function __zoxide_z_complete_helper() {\n        READLINE_LINE=\"z ${__zoxide_result@Q}\"\n        READLINE_POINT=${#READLINE_LINE}\n        bind \\'\"\\e[0n\": accept-line\\'\\n\n        \\builtin printf \\'\\e[5n\\' \\>\\>dev/tty\n    }\n\n    function __zoxide_z_complete() {\n        # Only show completions when the cursor is at the end of the line.\n        [[ ${#COMP_WORDS[@]} -eq $((COMP_CWORD + 1)) ]] || return\n\n        # If there is only one argument, use `cd` completions.\n        if [[ ${#COMP_WORDS[@]} -eq 2 ]]; then\n            \\builtin mapfile -t COMPREPLY \\< \\<(\n                \\builtin compgen -A directory -- \"${COMP_WORDS[-1]}\" || \\builtin true\n            )\n        # If there is a space after the last word, use interactive selection.\n        elif [[ -z ${COMP_WORDS[-1]} ]]; then\n            # shellcheck disable=SC2312\n            __zoxide_result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" --interactive -- \"${COMP_WORDS[@]:1:${#COMP_WORDS[@]}-2}\")\" \\&\\& {\n                # In case the terminal does not respond to \\e[5n or another\n                # mechanism steals the response, it is still worth completing\n                # the directory in the command line.\n                COMPREPLY=(\"${__zoxide_z_prefix}${__zoxide_result}/\")\n\n                # Note: We here call \"bind\" without prefixing \"\\builtin\" to be\n                # compatible with frameworks like ble.sh, which emulates Bash\\'s\n                # builtin \"bind\".\n                bind -x \\'\"\\e[0n\": __zoxide_z_complete_helper\\'\\n\n                \\builtin printf \\'\\e[5n\\' \\>\\>dev/tty\n            }\n        fi\n    }\n\n    \\builtin complete -F __zoxide_z_complete -o filenames -- z\n    \\builtin complete -r zi \\&\\>/dev/null || \\builtin true\nfi\n\n# =============================================================================\n#\n# To initialize zoxide, add this to your shell configuration file (usually ~/.bashrc):\n#\n# eval \"$(zoxide init bash)\"\n"
+        return 0
+
+    # Generate for other shells
+    if cmd is None:
+        cmd = "zoxide"
+    if hook is None:
+        hook = "__zoxide_hook"
+
+    if shell == "zsh":
+        return generate_zsh_init(cmd, no_cmd, hook)
